// The 25 passages closest in MEANING to the query — now let GPT judge which actually ANSWER it.
const query = $('When Executed by Another Workflow').first().json.query;
const passages = $input.all().map((it, i) => ({
  i,
  file_name: it.json.document?.metadata?.file_name,
  file_id: it.json.document?.metadata?.file_id,
  chunk_index: it.json.document?.metadata?.chunk_index,
  page_start: it.json.document?.metadata?.page_start,      // page numbers matched by the vision service (pages.py)
  page_end: it.json.document?.metadata?.page_end,
  page_best: it.json.document?.metadata?.page_best,     // the single best page: what look_at_pages opens
  similarity: it.json.score,
  content: it.json.document?.pageContent ?? '',
}));

// Show GPT the first 3,000 characters of each passage (headings + opening are enough to judge relevance)
const listing = passages.map(p => `[${p.i}] (${p.file_name})\n${p.content.slice(0, 3000)}`).join('\n\n---\n\n');

const prompt = `You are ranking search results for a question.
Question: ${query}

Below are ${passages.length} passages, numbered [n]. Choose up to 4 that most DIRECTLY help answer the question, best first.
Prefer passages containing the actual answer (steps, values, definitions, requirements) over passages that are only on a similar topic.
Return ONLY json: {"best": [n, n, ...]}. If none of them helps answer the question, return {"best": []}.

${listing}`;

// the local reranker reads the first 1,500 characters (3,000 was slower and no better; evals/rerank, 2026-10-24)
const docs = passages.map(p => p.content.slice(0, 1500));
return [{ json: { prompt, passages, query, docs } }];

// FALLBACK path: runs when the local reranker is unreachable, replies badly, or keeps nothing (off-topic or borderline).
// Turn GPT's choice into the tool's answer. If its reply is unusable, fall back to plain vector order —
// a search must never fail just because the reranker did.
const { passages } = $('Build rerank prompt').first().json;
const reply = $input.first().json;

let parsed = reply;                                         // n8n usually parses JSON replies already…
if (!Array.isArray(parsed.best)) {                          // …older versions give raw text
  try { parsed = JSON.parse(reply.text ?? reply.response ?? '{}'); } catch (e) { parsed = {}; }
}
let best = Array.isArray(parsed.best)
  ? parsed.best.map(Number).filter(n => Number.isInteger(n) && passages[n])
  : null;
const reranked = best !== null;
if (!reranked) best = [0, 1, 2, 3].filter(n => passages[n]);

const results = [...new Set(best)].slice(0, 4).map(n => ({
  file_name: passages[n].file_name,
  file_id: passages[n].file_id,
  chunk_index: passages[n].chunk_index,
  // pages this passage came from: cite them ("p. 14-16"); page_ref opens the page with look_at_pages
  page_range: passages[n].page_start == null ? undefined
    : (passages[n].page_start === passages[n].page_end ? `${passages[n].page_start}` : `${passages[n].page_start}-${passages[n].page_end}`),
  page_ref: passages[n].page_start == null ? undefined : `${passages[n].file_id}:${passages[n].page_best ?? passages[n].page_start}`,
  content: passages[n].content,                            // full text, image links included
}));
return [{ json: { reranked, ranker: reranked ? 'gpt' : 'vector', candidates: passages.length, picked: [...new Set(best)].slice(0, 4), results } }];

// Format the local reranker's picks exactly like the GPT path does.
const { passages } = $('Build rerank prompt').first().json;
const best = $json.best;
const results = best.map(n => ({
  file_name: passages[n].file_name,
  file_id: passages[n].file_id,
  chunk_index: passages[n].chunk_index,
  // pages this passage came from: cite them ("p. 14-16"); page_ref opens the page with look_at_pages
  page_range: passages[n].page_start == null ? undefined
    : (passages[n].page_start === passages[n].page_end ? `${passages[n].page_start}` : `${passages[n].page_start}-${passages[n].page_end}`),
  page_ref: passages[n].page_start == null ? undefined : `${passages[n].file_id}:${passages[n].page_best ?? passages[n].page_start}`,
  content: passages[n].content,                            // full text, image links included
}));
return [{ json: { reranked: true, ranker: 'local', candidates: passages.length, picked: best, results } }];

// Local reranker (bge-reranker-v2-m3 on this machine: no Azure tokens, ~1.4 s). Score = reranker score + 10 x the
// vector similarity; passages scoring below -3.5 are dropped. Measured on 64 questions (evals/rerank, 2026-10-24):
// right file in the top 4 83% vs GPT 78%; first place 66% vs 72%.
// Nothing kept (an off-topic question, or a borderline one: R13 scored below -3.5 yet was answerable), or an unusable
// reply -> the GPT reranker decides instead (Scrutiny 2026-10-24). GPT returns nothing for off-topic questions.
const { passages } = $('Build rerank prompt').first().json;
const res = Array.isArray($json.results) ? $json.results : null;
const best = !res ? [] : res
  .filter(r => Number.isInteger(r.index) && passages[r.index] && typeof r.relevance_score === 'number' && r.relevance_score >= -3.5)
  .map(r => ({ n: r.index, s: r.relevance_score + 10 * (Number(passages[r.index].similarity) || 0) }))
  .sort((a, b) => b.s - a.s).slice(0, 4).map(x => x.n);
return [{ json: { best } }];
